create table if not exists app_private.coach_opening_questions_v1 (
 persona_id text not null check (persona_id in ('mira','max','sofia','alex','merlin','harry')),
 step_key text not null check (step_key in ('invitation','name','continuity','focus','feelings','confirmation')),
 variant smallint not null check (variant between 1 and 4),
 prompt_i18n jsonb not null check (jsonb_typeof(prompt_i18n)='object' and prompt_i18n ?& array['en','ru','es']),
 version text not null default 'hh-opening-v1',
 enabled boolean not null default true,
 created_at timestamptz not null default now(),
 primary key (persona_id,step_key,variant)
);
alter table app_private.coach_opening_questions_v1 enable row level security;
alter table app_private.coach_opening_questions_v1 force row level security;
revoke all on table app_private.coach_opening_questions_v1 from public,anon,authenticated;
comment on table app_private.coach_opening_questions_v1 is 'Curated public editorial questions only: six opening steps, four persona variants, EN/RU/ES; no transcripts or client data.';
on conflict (persona_id,step_key,variant) do update set prompt_i18n=excluded.prompt_i18n,version='hh-opening-v1',enabled=true;