insert into app_private.coach_opening_questions_v1 (persona_id,step_key,variant,prompt_i18n) values
('mira','invitation',1,'{"en":"We can take this gently. Would you like to have a coaching session with me today?","ru":"Давайте бережно и без спешки. Хотите провести со мной коучинг-сессию сегодня?","es":"Podemos ir con suavidad. ¿Te gustaría tener una sesión de coaching conmigo hoy?"}'::jsonb),
('mira','invitation',2,'{"en":"There is no need to rush. Would you be willing to try a short coaching conversation with me?","ru":"Торопиться не нужно. Готовы попробовать со мной короткую коучинговую беседу?","es":"No hay prisa. ¿Te animas a probar una breve conversación de coaching conmigo?"}'::jsonb),
('mira','invitation',3,'{"en":"Your pace matters here. Shall we explore what matters to you together today?","ru":"Здесь важен ваш темп. Давайте сегодня вместе исследуем то, что для вас важно?","es":"Tu ritmo importa. ¿Exploramos hoy juntos lo que te importa?"}'::jsonb),
('mira','invitation',4,'{"en":"A small beginning is enough. Does a conversation together feel possible for you right now?","ru":"Можно начать с малого. Вам сейчас подходит идея немного поговорить вместе?","es":"Podemos empezar poco a poco. ¿Te parece posible que conversemos ahora?"}'::jsonb),
('mira','name',1,'{"en":"We can take this gently. What name would you like me to use?","ru":"Давайте бережно и без спешки. Как вам лучше обращаться?","es":"Podemos ir con suavidad. ¿Cómo te gustaría que te llamara?"}'::jsonb),
('mira','name',2,'{"en":"There is no need to rush. May I ask your name, or a nickname you prefer?","ru":"Торопиться не нужно. Как вас зовут или каким именем вам удобнее представиться?","es":"No hay prisa. ¿Cómo te llamas o qué apodo prefieres?"}'::jsonb),
('mira','name',3,'{"en":"Your pace matters here. How should I address you during our session?","ru":"Здесь важен ваш темп. Как мне обращаться к вам во время сессии?","es":"Tu ritmo importa. ¿Cómo debería dirigirme a ti durante la sesión?"}'::jsonb),
('mira','name',4,'{"en":"A small beginning is enough. What would you like me to call you?","ru":"Можно начать с малого. Как бы вы хотели, чтобы я вас называл(а)?","es":"Podemos empezar poco a poco. ¿Cómo prefieres que te llame?"}'::jsonb),
('mira','continuity',1,'{"en":"We can take this gently. Would you like to continue our previous topic or begin something new?","ru":"Давайте бережно и без спешки. Продолжим тему прошлой встречи или начнём новую?","es":"Podemos ir con suavidad. ¿Continuamos el tema anterior o empezamos uno nuevo?"}'::jsonb),
('mira','continuity',2,'{"en":"There is no need to rush. Does the earlier topic still matter today, or is there a new focus?","ru":"Торопиться не нужно. Прежняя тема всё ещё актуальна или сегодня другой запрос?","es":"No hay prisa. ¿Sigue importando el tema anterior o hay otro enfoque hoy?"}'::jsonb),
('mira','continuity',3,'{"en":"Your pace matters here. Shall we pick up where we left off, or choose a fresh subject?","ru":"Здесь важен ваш темп. Вернёмся к прошлому разговору или выберем другую тему?","es":"Tu ritmo importa. ¿Retomamos lo anterior o escogemos un asunto distinto?"}'::jsonb),
('mira','continuity',4,'{"en":"A small beginning is enough. Is today about that earlier question, or a new question?","ru":"Можно начать с малого. Сегодня работаем с прошлым вопросом или с новым?","es":"Podemos empezar poco a poco. ¿Hoy trabajamos en la pregunta anterior o en una nueva?"}'::jsonb),
('mira','focus',1,'{"en":"We can take this gently. Is today''s focus a challenge, a goal, or self-exploration?","ru":"Давайте бережно и без спешки. С чем работаем сегодня: с трудностью, целью или самоисследованием?","es":"Podemos ir con suavidad. ¿Trabajamos hoy un desafío, una meta o la autoexploración?"}'::jsonb),
('mira','focus',2,'{"en":"There is no need to rush. Would you like to solve a challenge, move toward a goal, or understand yourself better?","ru":"Торопиться не нужно. Хотите разобраться с трудностью, приблизиться к цели или лучше понять себя?","es":"No hay prisa. ¿Quieres explorar un desafío, avanzar hacia una meta o conocerte mejor?"}'::jsonb),
('mira','focus',3,'{"en":"Your pace matters here. Which fits best right now: challenge, goal, or self-exploration with profile and tests?","ru":"Здесь важен ваш темп. Что сейчас ближе: сложность, цель или самоисследование с профилем и тестами?","es":"Tu ritmo importa. ¿Qué encaja mejor: desafío, meta o autoexploración con perfil y pruebas?"}'::jsonb),
('mira','focus',4,'{"en":"A small beginning is enough. Do we start with a problem, a desired result, or an exploration of who you are?","ru":"Можно начать с малого. Начнём с проблемы, желаемого результата или исследования себя?","es":"Podemos empezar poco a poco. ¿Empezamos con un problema, un resultado deseado o una exploración personal?"}'::jsonb),
('mira','feelings',1,'{"en":"We can take this gently. How are you feeling today? You may also skip this question.","ru":"Давайте бережно и без спешки. Как вы себя сегодня чувствуете? Можно пропустить этот вопрос.","es":"Podemos ir con suavidad. ¿Cómo te sientes hoy? También puedes omitir la pregunta."}'::jsonb),
('mira','feelings',2,'{"en":"There is no need to rush. What feelings are with you as we begin?","ru":"Торопиться не нужно. Какие чувства вы замечаете в начале нашей беседы?","es":"No hay prisa. ¿Qué emociones notas al comenzar?"}'::jsonb),
('mira','feelings',3,'{"en":"Your pace matters here. How has your day felt emotionally, if you''d like to share?","ru":"Здесь важен ваш темп. Как проходит ваш день эмоционально, если хочется поделиться?","es":"Tu ritmo importa. ¿Cómo te has sentido hoy, si quieres compartirlo?"}'::jsonb),
('mira','feelings',4,'{"en":"A small beginning is enough. What is your inner weather right now, or would you rather not say?","ru":"Можно начать с малого. Какая сейчас у вас внутренняя погода — или лучше не говорить об этом?","es":"Podemos empezar poco a poco. ¿Cómo está tu clima interior ahora, o prefieres no decirlo?"}'::jsonb),
('mira','confirmation',1,'{"en":"We can take this gently. Shall we begin working with the topic you''ve chosen?","ru":"Давайте бережно и без спешки. Ну что, приступим к выбранной вами теме?","es":"Podemos ir con suavidad. ¿Empezamos a trabajar con el tema que elegiste?"}'::jsonb),
('mira','confirmation',2,'{"en":"There is no need to rush. Does it feel right to begin exploring this now?","ru":"Торопиться не нужно. Вам подходит начать исследовать это сейчас?","es":"No hay prisa. ¿Te parece bien empezar a explorar esto ahora?"}'::jsonb),
('mira','confirmation',3,'{"en":"Your pace matters here. Are you comfortable moving into the session with this focus?","ru":"Здесь важен ваш темп. Вам комфортно перейти к работе с этим запросом?","es":"Tu ritmo importa. ¿Te sientes a gusto pasando a la sesión con este enfoque?"}'::jsonb),
('mira','confirmation',4,'{"en":"A small beginning is enough. Would you like us to start now, or take a pause?","ru":"Можно начать с малого. Начнём сейчас или вам нужна пауза?","es":"Podemos empezar poco a poco. ¿Empezamos ahora o prefieres hacer una pausa?"}'::jsonb),
